// SolanaJsonRpcClient lines 824-866
  private <R> CompletableFuture<R> getAppliedAccounts(final Commitment commitment,
                                                      final BigInteger minContextSlot,
                                                      final int length,
                                                      final int offset,
                                                      final SequencedCollection<PublicKey> keys,
                                                      final BiFunction<JsonIterator, Context, R> adapter) {
    if (keys.isEmpty()) {
      throw new IllegalArgumentException("keys must not be empty");
    }

    final var builder = new StringBuilder(512);
    builder.append("""
        {"jsonrpc":"2.0","id":""");
    builder.append(id.incrementAndGet());

    builder.append("""
        ,"method":"getMultipleAccounts","params":[[""");
    final var iterator = keys.iterator();
    for (PublicKey key; ; ) {
      key = iterator.next();
      builder.append('"');
      builder.append(key.toBase58());
      builder.append('"');
      if (iterator.hasNext()) {
        builder.append(',');
      } else {
        break;
      }
    }

    builder.append("""
        ],{"encoding":"base64","commitment":\"""");
    builder.append(commitment.getValue());
    builder.append('"');

    appendMinContextSlot(builder, minContextSlot);

    appendDataSlice(builder, length, offset);

    builder.append("}]}");

    return sendPostRequest(applyGenericResponseValue(adapter), builder.toString());
  }
